export const consentRecords = sqliteTable(
  "consent_records",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    golferId: text("golfer_id"),
    subjectType: text("subject_type", { enum: ["account", "golfer"] }).notNull(),
    scope: text("scope", {
      enum: [
        "terms",
        "privacy_notice",
        "golfer_record",
        "roadmap_sharing",
        "media_use",
        "service_email",
        "optional_analytics",
      ],
    }).notNull(),
    status: text("status", { enum: consentStatuses }).notNull(),
    policyVersion: text("policy_version").notNull(),
    purposeDescription: text("purpose_description").notNull(),
    captureMethod: text("capture_method", {
      enum: ["self_service", "instructor_attested", "support_assisted", "imported"],
    }).notNull(),
    evidenceReference: text("evidence_reference"),
    recordedByAccountId: text("recorded_by_account_id").references(
      () => accounts.id,
      { onDelete: "set null" },
    ),
    grantedAt: timestamp("granted_at"),
    declinedAt: timestamp("declined_at"),
    withdrawnAt: timestamp("withdrawn_at"),
    expiresAt: timestamp("expires_at"),
    createdAt: createdAt(),
  },
  (table) => [
    foreignKey({
      name: "consent_records_account_fk",
      columns: [table.accountId],
      foreignColumns: [accounts.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "consent_records_golfer_tenant_fk",
      columns: [table.accountId, table.golferId],
      foreignColumns: [golfers.accountId, golfers.id],
    }).onDelete("no action"),
    uniqueIndex("consent_records_account_id_unique").on(table.accountId, table.id),
    index("consent_records_subject_scope_created_idx").on(
      table.accountId,
      table.golferId,
      table.scope,
      table.createdAt,
    ),
    index("consent_records_status_expires_idx").on(table.status, table.expiresAt),
    check(
      "consent_records_subject_type_check",
      sql`${table.subjectType} in ('account', 'golfer')`,
    ),
    check(
      "consent_records_subject_reference_check",
      sql`(${table.subjectType} = 'account' and ${table.golferId} is null) or (${table.subjectType} = 'golfer' and ${table.golferId} is not null)`,
    ),
    check(
      "consent_records_scope_check",
      sql`${table.scope} in ('terms', 'privacy_notice', 'golfer_record', 'roadmap_sharing', 'media_use', 'service_email', 'optional_analytics')`,
    ),
    check(
      "consent_records_status_check",
      sql`${table.status} in ('granted', 'declined', 'withdrawn', 'expired')`,
    ),
    check(
      "consent_records_capture_method_check",
      sql`${table.captureMethod} in ('self_service', 'instructor_attested', 'support_assisted', 'imported')`,
    ),
    check(
      "consent_records_status_timestamp_consistency_check",
      sql`(
        ${table.status} = 'granted'
        and ${table.grantedAt} is not null
        and ${table.grantedAt} <= ${table.createdAt}
        and ${table.declinedAt} is null
        and ${table.withdrawnAt} is null
        and (${table.expiresAt} is null or ${table.expiresAt} > ${table.grantedAt})
      ) or (
        ${table.status} = 'declined'
        and ${table.grantedAt} is null
        and ${table.declinedAt} is not null
        and ${table.declinedAt} <= ${table.createdAt}
        and ${table.withdrawnAt} is null
        and ${table.expiresAt} is null
      ) or (
        ${table.status} = 'withdrawn'
        and ${table.grantedAt} is null
        and ${table.declinedAt} is null
        and ${table.withdrawnAt} is not null
        and ${table.withdrawnAt} <= ${table.createdAt}
        and ${table.expiresAt} is null
      ) or (
        ${table.status} = 'expired'
        and ${table.grantedAt} is null
        and ${table.declinedAt} is null
        and ${table.withdrawnAt} is null
        and ${table.expiresAt} is not null
        and ${table.expiresAt} <= ${table.createdAt}
      )`,
    ),
  ],
);

